  "quick question"
]);

const newSubject = normalizeSubject(context.ticket.title || context.article.subject);
const subjectQuality = newSubject.length >= 12 && !genericSubjects.has(newSubject);
const newTicketId = asNumber(context.ticket.id);
const newCustomerId = asNumber(context.ticket.customer_id);
const newOrgId = asNumber(context.ticket.organization_id);
const allowedStateIds = new Set([1, 2, 3, 6]);
const now = Date.now();

const scoreTicket = (candidate) => {
  const candidateId = asNumber(candidate.id);
  const candidateSubject = normalizeSubject(candidate.title);
  const stateId = asNumber(candidate.state_id);
  const groupId = asNumber(candidate.group_id);
  const updatedAt = Date.parse(candidate.updated_at || candidate.created_at || "");
  const ageDays = Number.isFinite(updatedAt) && updatedAt > 0 ? Math.max(0, (now - updatedAt) / 86400000) : null;
  const sameCustomer = newCustomerId !== null && asNumber(candidate.customer_id) === newCustomerId;
  const sameOrg = newOrgId !== null && newOrgId !== 0 && asNumber(candidate.organization_id) === newOrgId;
  const subjectExact = subjectQuality && candidateSubject === newSubject;
  const subjectSimilarity = subjectQuality ? jaccard(newSubject, candidateSubject) : 0;
  const openish = allowedStateIds.has(stateId);
  const sameGroup = groupId === context.ticket.group_id;
  const notSelf = candidateId !== newTicketId;
  const recent60 = ageDays !== null && ageDays <= 60;

  const reasons = [];
  const blocking_flags = [];
  let score = 0;

  if (sameGroup) { score += 10; reasons.push("same_group"); } else blocking_flags.push("different_group");
  if (openish) { score += 10; reasons.push("openish_state"); } else blocking_flags.push("closed_or_merged_state");
  if (sameCustomer) { score += 40; reasons.push("same_customer"); }
  if (sameOrg) { score += 15; reasons.push("same_organization"); }
  if (subjectExact) { score += 35; reasons.push("exact_normalized_subject"); }
  else if (subjectSimilarity >= 0.75) { score += 25; reasons.push("high_subject_similarity"); }
  else if (subjectSimilarity >= 0.45) { score += 12; reasons.push("partial_subject_similarity"); }
  if (ageDays !== null && ageDays <= 7) { score += 15; reasons.push("updated_within_7_days"); }
  else if (ageDays !== null && ageDays <= 30) { score += 10; reasons.push("updated_within_30_days"); }
  else if (recent60) { score += 5; reasons.push("updated_within_60_days"); }
  else blocking_flags.push("outside_60_day_window");
  if (!notSelf) blocking_flags.push("self_ticket");
  if (!subjectQuality) blocking_flags.push("generic_or_short_subject");

  let match_tier = "no_match";
  if (notSelf && sameGroup && openish && recent60 && sameCustomer && subjectExact && subjectQuality) {
    match_tier = "exact_composite_ticket_level";
  } else if (notSelf && sameGroup && openish && recent60 && (sameCustomer || sameOrg) && subjectSimilarity >= 0.75 && subjectQuality) {
    match_tier = "strong_composite_ticket_level";
  } else if (notSelf && sameGroup && openish && recent60 && score >= 45 && (subjectSimilarity >= 0.45 || sameOrg)) {
    match_tier = "fuzzy_ticket_level";
  }

  return {
    id: candidateId,
    number: candidate.number ?? null,
    title: candidate.title ?? null,
    group_id: groupId,
    state_id: stateId,
    customer_id: asNumber(candidate.customer_id),
    organization_id: asNumber(candidate.organization_id),
    created_at: candidate.created_at ?? null,
    updated_at: candidate.updated_at ?? null,
    normalized_subject: candidateSubject,
    subject_similarity: Number(subjectSimilarity.toFixed(3)),
    age_days: ageDays === null ? null : Number(ageDays.toFixed(1)),
    deterministic_score: score,
    match_tier,
    reasons,
    blocking_flags
  };
};

const allCandidates = flattenTickets(inputItems);
const createdTime = (candidate) => {
  const parsed = Date.parse(candidate.created_at || "");
  return Number.isFinite(parsed) && parsed > 0 ? parsed : Number.MAX_SAFE_INTEGER;
};

const scored = allCandidates
  .map(scoreTicket)
  .filter((candidate) => !candidate.blocking_flags.includes("self_ticket"))
  .sort((a, b) => {
    const tierRank = {
      exact_composite_ticket_level: 4,
      strong_composite_ticket_level: 3,
      fuzzy_ticket_level: 2,
      no_match: 1
    };
    const rankDiff = (tierRank[b.match_tier] || 0) - (tierRank[a.match_tier] || 0);
    if (rankDiff !== 0) return rankDiff;
    if (b.deterministic_score !== a.deterministic_score) return b.deterministic_score - a.deterministic_score;
    if (b.subject_similarity !== a.subject_similarity) return b.subject_similarity - a.subject_similarity;
    const createdDiff = createdTime(a) - createdTime(b);
    if (createdDiff !== 0) return createdDiff;
    return (a.id ?? Number.MAX_SAFE_INTEGER) - (b.id ?? Number.MAX_SAFE_INTEGER);
  });

const viable = scored.filter((candidate) => candidate.match_tier !== "no_match");
const exactComposite = viable.filter((candidate) => candidate.match_tier === "exact_composite_ticket_level");
const topCandidates = viable.slice(0, 5);
const highConfidenceCandidate = exactComposite.length === 1 ? exactComposite[0] : null;

const candidateLookup = {
  strategy: "deterministic_ticket_level_v1",
  query: "group_id:2",
  searched_count: allCandidates.length,
  scored_count: scored.length,
  viable_count: viable.length,
  top_count: topCandidates.length,
  new_normalized_subject: newSubject,
  subject_quality: subjectQuality,
  hard_gate_unique_match: Boolean(highConfidenceCandidate),
  recommendation: highConfidenceCandidate ? "high_confidence_review" : (topCandidates.length > 0 ? "candidate_review" : "no_candidate"),
  top_candidate_id: highConfidenceCandidate?.id ?? topCandidates[0]?.id ?? null,
  top_candidate_number: highConfidenceCandidate?.number ?? topCandidates[0]?.number ?? null,
  top_candidates: topCandidates
};

return { json: { ...context, candidate_lookup: candidateLookup } };

const data = $json;
const lookup = data.candidate_lookup || {};
const top = lookup.top_candidates || [];
const shouldWrite = ["high_confidence_review", "candidate_review"].includes(lookup.recommendation) && top.length > 0;

const escapeHtml = (value) => String(value ?? "")
  .replace(/&/g, "&amp;")
  .replace(/</g, "&lt;")
  .replace(/>/g, "&gt;")
  .replace(/"/g, "&quot;");

const candidateLines = top.slice(0, 5).map((candidate, index) => {
  const reasons = (candidate.reasons || []).join(", ") || "none";
  const flags = (candidate.blocking_flags || []).length ? `; flags: ${(candidate.blocking_flags || []).join(", ")}` : "";
  return `<li><strong>${index + 1}. #${escapeHtml(candidate.number)}</strong> - ${escapeHtml(candidate.title)}<br/>Tier: ${escapeHtml(candidate.match_tier)}; score: ${escapeHtml(candidate.deterministic_score)}; subject similarity: ${escapeHtml(candidate.subject_similarity)}<br/>Reasons: ${escapeHtml(reasons)}${escapeHtml(flags)}</li>`;
}).join("\n");

const recommendationLabel = lookup.recommendation === "high_confidence_review"
  ? "High-confidence possible follow-up"
  : "Possible follow-up candidates";

const body = `<p><strong>${escapeHtml(recommendationLabel)}</strong></p>
<p>n8n reviewed this new HIT ticket for possible marker-less follow-up recovery.</p>
<ul>
  <li>New ticket: #${escapeHtml(data.ticket?.number || data.ticket?.id)} - ${escapeHtml(data.ticket?.title)}</li>
  <li>Recommendation: ${escapeHtml(lookup.recommendation)}</li>
  <li>Hard-gate unique match: ${escapeHtml(Boolean(lookup.hard_gate_unique_match))}</li>
  <li>Source article: ${escapeHtml(data.article?.id)} from ${escapeHtml(data.article?.from)}</li>
  <li>Normalized subject: ${escapeHtml(lookup.new_normalized_subject)}</li>
</ul>
<p><strong>Ranked candidates</strong></p>
<ol>${candidateLines}</ol>
<p>No automatic merge or ticket mutation was performed beyond this internal note.</p>`;

return {
  json: {
    ...data,
    review_note: {
      should_write: shouldWrite,
      attempted: false,
      written: false,
      subject: `Possible follow-up detected for #${data.ticket?.number || data.ticket?.id}`,
      payload: shouldWrite ? {
        ticket_id: data.ticket.id,
        subject: `Possible follow-up detected for #${data.ticket?.number || data.ticket?.id}`,
        body,
        content_type: "text/html",
        type: "note",
        internal: true,
        sender: "Agent"
      } : null
    }
  }
};

const original = $("Prepare Review Note").first().json;
const response = $input.first().json;
const createdId = response?.id ?? response?.body?.id ?? null;

return {
  json: {
    ...original,
    review_note: {
      ...original.review_note,
      attempted: true,
      written: Boolean(createdId),
      article_id: createdId,
      response_status: response?.statusCode ?? response?.status ?? null
    }
  }
};
